function textContent(node: ReactDevHtmlNode): string {
  return node.type === 'text' ? node.value : node.children.map(textContent).join('')
}

function replaceElementText(root: ReactDevHtmlNode, tagName: string, replacement: string, last = false): void {
  const matches: ReactDevHtmlNode[] = []
  const visit = (node: ReactDevHtmlNode) => {
    if (node.type !== 'element') return
    if (node.tag === tagName) matches.push(node)
    node.children.forEach(visit)
  }
  visit(root)
  const node = last ? matches.at(-1) : matches[0]
  if (node?.type === 'element') node.children = [{ type: 'text', value: replacement }]
}

function replaceLead(root: ReactDevHtmlNode, replacement: string): void {
  let headingFound = false
  let leadFound = false
  const visit = (node: ReactDevHtmlNode): void => {
    if (node.type !== 'element' || leadFound) return
    if (node.tag === 'h1' || node.tag === 'h2') headingFound = true
    else if (headingFound && node.tag === 'p') {
      node.children = [{ type: 'text', value: replacement }]
      leadFound = true
      return
    }
    node.children.forEach(visit)
  }
  visit(root)
}

function replaceCodeSnippet(root: ReactDevHtmlNode, source: string): void {
  const blocks: Array<{ code: ReactDevHtmlNode; pre?: ReactDevHtmlNode }> = []
  const visit = (node: ReactDevHtmlNode, parent?: ReactDevHtmlNode) => {
    if (node.type !== 'element') return
    if (node.tag === 'code' && typeof node.attrs.class === 'string' && node.attrs.class.includes('sp-pre-placeholder')) blocks.push({ code: node, pre: parent })
    node.children.forEach((child) => visit(child, node))
  }
  visit(root)
  const block = blocks[0]
  if (!block || block.code.type !== 'element') return
  if (block.pre?.type === 'element' && typeof block.pre.attrs.class === 'string') {
    block.pre.attrs.class = block.pre.attrs.class.replace(/sp-(?:javascript|jsx|typescript|tsx|html|json|css)(?=\s|$)/, 'sp-rust')
  }
  const lines = source.replace(/\n$/, '').split('\n')
  block.code.children = lines.map((line) => ({
    type: 'element', tag: 'div', attrs: { class: 'cm-line' },
    children: line ? [{ type: 'element', tag: 'span', attrs: { class: 'sp-syntax-plain' }, children: [{ type: 'text', value: line }] }] : [{ type: 'element', tag: 'br', attrs: {}, children: [] }],
  }))
}

function applyPreviewItems(root: ReactDevHtmlNode, items?: ReactDevPreviewItem[], countLabel?: string): void {
  if (!items) return
  let index = 0
  const setText = (node: ReactDevHtmlNode, tag: string, value: string): boolean => {
    if (node.type !== 'element') return false
    if (node.tag === tag) { node.children = [{ type: 'text', value }]; return true }
    return node.children.some((child) => setText(child, tag, value))
  }
  const visit = (node: ReactDevHtmlNode): void => {
    if (node.type !== 'element') return
    node.children = node.children.filter((child) => {
      if (child.type === 'element' && child.attrs['data-hover'] === 'Video') {
        const item = items[index++]
        if (!item) return false
        setText(child, 'h3', item.title)
        setText(child, 'p', item.description)
        return true
      }
      visit(child)
      return true
    })
    if (countLabel && node.attrs['data-hover'] === 'h2') node.children = [{ type: 'text', value: countLabel }]
  }
  visit(root)
}

function iconNode(name: ReactDevIcon): VNode {
  const paths: Record<ReactDevIcon, string> = {
    arrow: 'M4 12h15M13 5l7 7-7 7',
    code: 'm8 8-4 4 4 4m8-8 4 4-4 4m-2-11-4 14',
    framework: 'M12 4v6m8 2h-6m-2 8v-6m-8-2h6',
    native: 'M8 3h8a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2Zm2 14h4',
    news: 'M4 4h16v16H4zM8 8h8m-8 4h8m-8 4h5',
  }
  const children: VNode[] = [h('path', { d: paths[name] })]
  if (name === 'framework') children.unshift(h('circle', { cx: '12', cy: '12', r: '8' }), h('circle', { cx: '12', cy: '12', r: '2' }))
  if (name === 'news') children[0] = h('path', { d: 'M4 4h16v16H4z' }), children.push(h('path', { d: 'M8 8h8m-8 4h8m-8 4h5' }))
  return h('svg', { viewBox: '0 0 24 24', width: 20, height: 20, fill: 'none', stroke: 'currentColor', 'stroke-width': 1.8, 'stroke-linecap': 'round', 'stroke-linejoin': 'round', 'aria-hidden': 'true' }, children)
}

function renderNode(node: ReactDevHtmlNode, actions: ReactDevAction[]): VNode | string | null {
  if (node.type === 'text') return node.value
  if (node.type === 'fragment') {
    const children = node.children.map((child) => renderNode(child, actions)).filter((child): child is VNode | string => child !== null)
    return h(Fragment, null, children)
  }
  if (node.tag === 'a') {
    const label = textContent(node).replace(/\s+/g, ' ').trim()
    const action = actions.find((item) => item.sourceHref === node.attrs.href)
    if (action) {
      const primary = action.style === 'primary'
      return h(FeluqaButton, {
        tag: 'a',
        href: action.href,
        size: 'lg',
        radius: 18,
        color: primary ? 'primary' : 'gray',
        outlined: !primary,
        iconPosition: action.style === 'cta' ? 'before' : 'after',
        class: action.style === 'cta' ? 'react-dev-action react-dev-action--cta' : 'react-dev-action react-dev-action--hero',
        'aria-label': action.label,
      }, {
        default: () => action.label,
        ...(action.icon ? { icon: () => iconNode(action.icon!) } : {}),
      })
    }
  }
  const attrs = { ...node.attrs }
  if (typeof attrs.src === 'string') attrs.src = localizeReactAssets(attrs.src)
  if (typeof attrs.href === 'string' && attrs.href.startsWith('/')) attrs.href = `https://react.dev${attrs.href}`
  const children = node.children.map((child) => renderNode(child, actions)).filter((child): child is VNode | string => child !== null)
  return h(node.tag, attrs, children)
}

function injectContent(root: ReactDevHtmlNode, content?: string[]): void {
  let index = 0
  const visit = (node: ReactDevHtmlNode, inCode = false): void => {
    if (node.type === 'text') {
      if (!inCode) node.value = content?.[index++] ?? ''
      return
    }
    const code = node.type === 'element' && node.tag === 'code' && String(node.attrs.class ?? '').includes('sp-pre-placeholder')
    node.children.forEach((child) => visit(child, inCode || code))
  }
  visit(root)
}

function renderReactDevBlock(source: ReactDevHtmlNode, text: ReactDevText, headingTag: 'h1' | 'h2' = 'h2'): VNode {
  const tree = JSON.parse(JSON.stringify(source)) as ReactDevHtmlNode
  injectContent(tree, text.content)
  if (text.title !== undefined) replaceElementText(tree, headingTag, text.title)
  if (text.lead !== undefined) replaceLead(tree, text.lead)
  if (text.detail !== undefined) replaceElementText(tree, 'p', text.detail, true)
  if (text.codeLines !== undefined) replaceCodeSnippet(tree, text.codeLines.join('\n'))
  if (text.codeTitle !== undefined) replaceElementText(tree, 'h3', text.codeTitle)
  applyPreviewItems(tree, text.previewItems, text.previewCountLabel)
  return h('div', { class: 'react-dev-block' }, renderNode(tree, text.actions ?? []))
}

export default defineComponent({
  name: 'ReactDevBlockComponents',
  props: {
    title: String,
    lead: String,
    detail: String,
    content: Array as PropType<string[]>,
    markupTitle: String,
    markupLead: String,
    markupDetail: String,
    markupContent: Array as PropType<string[]>,
    codeLines: Array as PropType<string[]>,
    codeTitle: String,
    markupCodeLines: Array as PropType<string[]>,
    markupCodeTitle: String,
    previewItems: Array as PropType<ReactDevPreviewItem[]>,
    previewCountLabel: String,
  },
  setup(props) {
    return () => h(Fragment, null, [
      renderReactDevBlock(components, { title: props.title, lead: props.lead, detail: props.detail, content: props.content, codeLines: props.codeLines, codeTitle: props.codeTitle, previewItems: props.previewItems }),
      renderReactDevBlock(markup, { title: props.markupTitle, lead: props.markupLead, detail: props.markupDetail, content: props.markupContent, codeLines: props.markupCodeLines, codeTitle: props.markupCodeTitle, previewItems: props.previewItems, previewCountLabel: props.previewCountLabel }),
    ])
  }
})
</script>

